class Collection
{
    public function __construct(private RequestInterface $request)
    {
        $this->request = $request;
    }

	public function beforeLoadProductCount(\Magento\Catalog\Model\ResourceModel\Category\Collection $subject, $items, $countRegular = true, $countAnchor = true)
	{
		$routeInfo = $this->getRouteInfo();
		if ($routeInfo['route_name'] == 'catalog' && $routeInfo['controller_name'] == 'category' && ($routeInfo['action_name'] == 'edit' || $routeInfo['action_name'] == 'new')) {
